import{_ as l,a0 as o,w as d,s as r,ao as p,I as a,x as e,a1 as i,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"在 Linux 中複製文檔 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 中複製文檔 | LCTT (201908) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 中複製文檔 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 中複製文檔 | LCTT (201908) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201908/20190809 Copying files in Linux","title":"在 Linux 中複製文檔","tag":"201908","desc":""},"relativePath":"201908/20190809 Copying files in Linux.md","filePath":"[post].md"}'),c={name:"201908/20190809 Copying files in Linux.md"};function u(g,s,h,k,b,m){const n=o("Link");return d(),r("div",null,[s[40]||(s[40]=p('<h1 id="在-linux-中複製文檔" tabindex="-1">在 Linux 中複製文檔 <a class="header-anchor" href="#在-linux-中複製文檔" aria-label="Permalink to “在 Linux 中複製文檔”">​</a></h1><blockquote><p>瞭解在 Linux 中多種複製文檔的方式以及各自的優點。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/201908/23/053859f1stcjezllmj28e8.jpg" alt=""></p><p>在辦公室裏複印文檔過去需要專門的員工與機器。如今，複製是電腦用户無需多加思考的任務。在電腦裏複製數據是如此微不足道的事，以致於你還沒有意識到複製就發生了，例如當拖動文檔到外部硬盤的時候。</p><p>數字實體複製起來十分簡單已是一個不爭的事實，以致於大部分現代電腦用户從未考慮過其它的複製他們工作的方式。無論如何，在 Linux 中複製文檔仍有幾種不同的方式。每種方法取決於你的目的不同而都有其獨到之處。</p><p>以下是一系列在 Linux、BSD 及 Mac 上覆制文件的方式。</p><h3 id="在-gui-中複製" tabindex="-1">在 GUI 中複製 <a class="header-anchor" href="#在-gui-中複製" aria-label="Permalink to “在 GUI 中複製”">​</a></h3><p>如大多數操作系統一樣，如果你想的話，你可以完全用 GUI 來管理文件。</p><h4 id="拖拽放下" tabindex="-1">拖拽放下 <a class="header-anchor" href="#拖拽放下" aria-label="Permalink to “拖拽放下”">​</a></h4><p>最淺顯的複製文件的方式可能就是你以前在電腦中複製文件的方式：拖拽並放下。在大多數 Linux 桌面上，從一個本地文件夾拖拽放下到另一個本地文件夾是<em>移動</em>文件的默認方式，你可以通過在拖拽文件開始後按住 <code>Ctrl</code> 來改變這個行為。</p><p>你的鼠標指針可能會有一個指示，例如一個加號以顯示你在複製模式。</p><p><img src="https://opensource.com/sites/default/files/uploads/copy-nautilus.jpg" alt="複製一個文件" title="Copying a file."></p><p>注意如果文件是放在遠程系統上的，不管它是一個 Web 服務器還是在你自己網絡裏用文件共享協議訪問的另一台電腦，默認動作經常是複製而不是移動文件。</p><h4 id="右擊" tabindex="-1">右擊 <a class="header-anchor" href="#右擊" aria-label="Permalink to “右擊”">​</a></h4><p>如果你覺得在你的桌面拖拽文檔不夠精準或者有點笨拙，或者這麼做會讓你的手離開鍵盤太久，你可以經常使用右鍵菜單來複制文件。這取決於你所用的文件管理器，但通常來説，右鍵彈出的關聯菜單會包括常見的操作。</p>',15)),a("p",null,[s[1]||(s[1]=e("關聯菜單的“複製”動作將你的",-1)),i(n,{href:"https://opensource.com/article/19/7/understanding-file-paths-and-how-use-them"},{default:t(()=>[...s[0]||(s[0]=[e("文件路徑",-1)])]),_:1}),s[2]||(s[2]=e("（即文件在系統的位置）保存在你的剪切板中，這樣你可以將你的文件",-1)),s[3]||(s[3]=a("em",null,"粘貼",-1)),s[4]||(s[4]=e("到別處：（LCTT 譯註：此處及下面的描述不確切，這裏並非複製的文件路徑的“字符串”，而是複製了代表文件實體的對象/指針）",-1))]),s[41]||(s[41]=a("p",null,[a("img",{src:"https://opensource.com/sites/default/files/uploads/copy-files-menu.jpg",alt:"從右鍵菜單複製文件",title:"Copying a file from the context menu."})],-1)),a("p",null,[s[6]||(s[6]=e("在這種情況下，你並沒有將文件的內容複製到你的剪切版上。取而代之的是你複製了",-1)),i(n,{href:"https://opensource.com/article/19/7/understanding-file-paths-and-how-use-them"},{default:t(()=>[...s[5]||(s[5]=[e("文件路徑",-1)])]),_:1}),s[7]||(s[7]=e("。當你粘貼時，你的文件管理器會查看剪貼板上的路徑並執行復制命令，將相應路徑上的文件粘貼到你準備複製到的路徑。",-1))]),s[42]||(s[42]=p(`<h3 id="用命令列複製" tabindex="-1">用命令列複製 <a class="header-anchor" href="#用命令列複製" aria-label="Permalink to “用命令列複製”">​</a></h3><p>雖然 GUI 通常是相對熟悉的複製文件方式，用終端複製卻更有效率。</p><h4 id="cp" tabindex="-1">cp <a class="header-anchor" href="#cp" aria-label="Permalink to “cp”">​</a></h4><p>在終端上等同於在桌面上複製和粘貼文件的最顯而易見的方式就是 <code>cp</code> 命令。這個命令可以複製文件和目錄，也相對直接。它使用熟悉的<em>來源</em>和<em>目的</em>（必須以這樣的順序）句法，因此複製一個名為 <code>example.txt</code> 的文件到你的 <code>Documents</code> 目錄就像這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cp example.txt ~/Documents</span></span></code></pre></div><p>就像當你拖拽文件放在文件夾裏一樣，這個動作並不會將 <code>Documents</code> 替換為 <code>example.txt</code>。取而代之的是，<code>cp</code> 察覺到 <code>Documents</code> 是一個文件夾，就將 <code>example.txt</code> 的副本放進去。</p><p>你同樣可以便捷有效地重命名你複製的文檔：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cp example.txt ~/Documents/example_copy.txt</span></span></code></pre></div><p>重要的是，它使得你可以在與原文件相同的目錄中生成一個副本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cp example.txt example.txt</span></span>
<span class="line"><span>cp: &#39;example.txt&#39; and &#39;example.txt&#39; are the same file.</span></span>
<span class="line"><span>$ cp example.txt example_copy.txt</span></span></code></pre></div><p>要複製一個目錄，你必須使用 <code>-r</code> 選項（代表 <code>--recursive</code>，遞歸）。以這個選項對目錄 <code>nodes</code> 運行 <code>cp</code> 命令，然後會作用到該目錄下的所有文件。沒有 <code>-r</code> 選項，<code>cp</code> 不會將目錄當成一個可複製的對象：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cp notes/ notes-backup</span></span>
<span class="line"><span>cp: -r not specified; omitting directory &#39;notes/&#39;</span></span>
<span class="line"><span>$ cp -r notes/ notes-backup</span></span></code></pre></div><h4 id="cat" tabindex="-1">cat <a class="header-anchor" href="#cat" aria-label="Permalink to “cat”">​</a></h4>`,13)),a("p",null,[s[10]||(s[10]=a("code",null,"cat",-1)),s[11]||(s[11]=e(" 命令是最易被誤解的命令，但這只是因為它表現了 ",-1)),i(n,{href:"https://linux.cn/article-11222-1.html"},{default:t(()=>[...s[8]||(s[8]=[e("POSIX",-1)])]),_:1}),s[12]||(s[12]=e(" 系統的極致靈活性。在 ",-1)),s[13]||(s[13]=a("code",null,"cat",-1)),s[14]||(s[14]=e(" 可以做到的所有事情中（包括其原意的連接文件的用途），它也能複製。例如説使用 ",-1)),s[15]||(s[15]=a("code",null,"cat",-1)),s[16]||(s[16]=e(" 你可以僅用一個命令就",-1)),i(n,{href:"https://opensource.com/article/19/2/getting-started-cat-command"},{default:t(()=>[...s[9]||(s[9]=[e("從一個文件創建兩個副本",-1)])]),_:1}),s[17]||(s[17]=e("。你用 ",-1)),s[18]||(s[18]=a("code",null,"cp",-1)),s[19]||(s[19]=e(" 無法做到這一點。",-1))]),s[43]||(s[43]=p(`<p>使用 <code>cat</code> 複製文檔要注意的是系統解釋該行為的方式。當你使用 <code>cp</code> 複製文件時，該文件的屬性跟着文件一起被複制，這意味着副本的權限和原件一樣。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l -G -g</span></span>
<span class="line"><span>-rw-r--r--. 1 57368 Jul 25 23:57  foo.jpg</span></span>
<span class="line"><span>$ cp foo.jpg bar.jpg</span></span>
<span class="line"><span>-rw-r--r--. 1 57368 Jul 29 13:37  bar.jpg</span></span>
<span class="line"><span>-rw-r--r--. 1 57368 Jul 25 23:57  foo.jpg</span></span></code></pre></div>`,2)),a("p",null,[s[21]||(s[21]=e("然而用 ",-1)),s[22]||(s[22]=a("code",null,"cat",-1)),s[23]||(s[23]=e(" 將一個文件的內容讀取至另一個文件是讓系統創建了一個新文件。這些新文件取決於你的默認 umask 設置。要了解 umask 更多的知識，請閲讀 Alex Juarez 講述 ",-1)),i(n,{href:"https://opensource.com/article/19/7/linux-permissions-101"},{default:t(()=>[...s[20]||(s[20]=[e("umask",-1)])]),_:1}),s[24]||(s[24]=e(" 以及權限概覽的文章。",-1))]),s[44]||(s[44]=p(`<p>運行 <code>unmask</code> 獲取當前設置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ umask</span></span>
<span class="line"><span>0002</span></span></code></pre></div><p>這個設置代表在該處新創建的文檔被給予 <code>664</code>（<code>rw-rw-r--</code>）權限，因為該 <code>unmask</code> 設置的前幾位數字沒有遮掩任何權限（而且執行位不是文件創建的默認位），並且寫入權限被最終位所屏蔽。</p><p>當你使用 <code>cat</code> 複製時，實際上你並沒有真正複製文件。你使用 <code>cat</code> 讀取文件內容並將輸出重定向到了一個新文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat foo.jpg &amp;gt; baz.jpg</span></span>
<span class="line"><span>$ ls -l -G -g</span></span>
<span class="line"><span>-rw-r--r--. 1 57368 Jul 29 13:37  bar.jpg</span></span>
<span class="line"><span>-rw-rw-r--. 1 57368 Jul 29 13:42  baz.jpg</span></span>
<span class="line"><span>-rw-r--r--. 1 57368 Jul 25 23:57  foo.jpg</span></span></code></pre></div><p>如你所見，<code>cat</code> 應用系統默認的 umask 設置創建了一個全新的文件。</p><p>最後，當你只是想複製一個文件時，這些手段無關緊要。但如果你想複製文件並保持默認權限時，你可以用一個命令 <code>cat</code> 完成一切。</p><h4 id="rsync" tabindex="-1">rsync <a class="header-anchor" href="#rsync" aria-label="Permalink to “rsync”">​</a></h4><p>有着著名的同步源和目的文件的能力，<code>rsync</code> 命令是一個複製文件的多才多藝的工具。最為簡單的，<code>rsync</code> 可以類似於 <code>cp</code> 命令一樣使用。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rsync example.txt example_copy.txt</span></span>
<span class="line"><span>$ ls</span></span>
<span class="line"><span>example.txt    example_copy.txt</span></span></code></pre></div><p>這個命令真正的威力藏在其能夠<em>不做</em>不必要的複製的能力裏。如果你使用 <code>rsync</code> 來將文件複製進目錄裏，且其已經存在在該目錄裏，那麼 <code>rsync</code> 不會做複製操作。在本地這個差別不是很大，但如果你將海量數據複製到遠程服務器，這個特性的意義就完全不一樣了。</p><p>甚至在本地中，真正不一樣的地方在於它可以分辨具有相同名字但擁有不同數據的文件。如果你曾發現你面對着同一個目錄的兩個相同副本時，<code>rsync</code> 可以將它們同步至一個包含每一個最新修改的目錄。這種配置在尚未發現版本控制威力的業界十分常見，同時也作為需要從一個可信來源複製的備份方案。</p><p>你可以通過創建兩個文件夾有意識地模擬這種情況，一個叫做 <code>example</code> 另一個叫做 <code>example_dupe</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir example example_dupe</span></span></code></pre></div><p>在第一個文件夾裏創建文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;one&quot; &gt; example/foo.txt</span></span></code></pre></div><p>用 <code>rsync</code> 同步兩個目錄。這種做法最常見的選項是 <code>-a</code>（代表 “archive”，可以保證符號鏈接和其它特殊文件保留下來）和 <code>-v</code>（代表 “verbose”，向你提供當前命令的進度反饋）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rsync -av example/ example_dupe/</span></span></code></pre></div><p>兩個目錄現在包含同樣的信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat example/foo.txt</span></span>
<span class="line"><span>one</span></span>
<span class="line"><span>$ cat example_dupe/foo.txt</span></span>
<span class="line"><span>one</span></span></code></pre></div><p>如果你當作源分支的文件發生改變，目的文件也會隨之跟新：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;two&quot; &gt;&gt; example/foo.txt</span></span>
<span class="line"><span>$ rsync -av example/  example_dupe/</span></span>
<span class="line"><span>$ cat example_dupe/foo.txt</span></span>
<span class="line"><span>one</span></span>
<span class="line"><span>two</span></span></code></pre></div><p>注意 <code>rsync</code> 命令是用來複制數據的，而不是充當版本管理系統的。例如假設有一個目的文件比源文件多了改變，那個文件仍將被覆蓋，因為 <code>rsync</code> 比較文件的分歧並假設目的文件總是應該鏡像為源文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;You will never see this note again&quot; &amp;gt; example_dupe/foo.txt</span></span>
<span class="line"><span>$ rsync -av example/  example_dupe/</span></span>
<span class="line"><span>$ cat example_dupe/foo.txt</span></span>
<span class="line"><span>one</span></span>
<span class="line"><span>two</span></span></code></pre></div><p>如果沒有改變，那麼就不會有複製動作發生。</p><p><code>rsync</code> 命令有許多 <code>cp</code> 沒有的選項，例如設置目標權限、排除文件、刪除沒有在兩個目錄中出現的過時文件，以及更多。可以使用 <code>rsync</code> 作為 <code>cp</code> 的強力替代或者有效補充。</p><h3 id="許多複製的方式" tabindex="-1">許多複製的方式 <a class="header-anchor" href="#許多複製的方式" aria-label="Permalink to “許多複製的方式”">​</a></h3><p>在 POSIX 系統中有許多能夠達成同樣目的的方式，因此開源的靈活性名副其實。我忘了哪個複製數據的有效方式嗎？在評論區分享你的複製神技。</p><hr>`,29)),a("p",null,[s[26]||(s[26]=e("via: ",-1)),i(n,{href:"https://opensource.com/article/19/8/copying-files-linux"},{default:t(()=>[...s[25]||(s[25]=[e("https://opensource.com/article/19/8/copying-files-linux",-1)])]),_:1})]),a("p",null,[s[31]||(s[31]=e("作者：",-1)),i(n,{href:"https://opensource.com/users/seth"},{default:t(()=>[...s[27]||(s[27]=[e("Seth Kenlon",-1)])]),_:1}),s[32]||(s[32]=e(" 選題：",-1)),i(n,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[28]||(s[28]=[e("lujun9972",-1)])]),_:1}),s[33]||(s[33]=e(" 譯者：",-1)),i(n,{href:"https://github.com/tomjlw"},{default:t(()=>[...s[29]||(s[29]=[e("tomjlw",-1)])]),_:1}),s[34]||(s[34]=e(" 校對：",-1)),i(n,{href:"https://github.com/wxy"},{default:t(()=>[...s[30]||(s[30]=[e("wxy",-1)])]),_:1})]),a("p",null,[s[37]||(s[37]=e("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[35]||(s[35]=[e("LCTT",-1)])]),_:1}),s[38]||(s[38]=e(" 原創編譯，",-1)),i(n,{href:"https://linux.cn/"},{default:t(()=>[...s[36]||(s[36]=[e("Linux中國",-1)])]),_:1}),s[39]||(s[39]=e(" 榮譽推出",-1))])])}const C=l(c,[["render",u]]);export{y as __pageData,C as default};
